function TF(k,vars={}){let out=T(k);for(const [key,val] of Object.entries(vars))out=out.replaceAll('{'+key+'}',String(val));return out}
const GEO_SESSION_KEY='raluvaaaApproxPlaceV1';
function currentLanguage(){return state.lang==='en'?'en':'fr'}
function approximatePlaceFromAddress(a){
  const city=a?.city||a?.town||a?.village||a?.municipality||a?.borough||a?.county||'';
  const country=a?.country||'';
  return [city,country].filter(Boolean).join(', ')
}
async function reversePlace(lat,lon){
  const u=new URL('https://nominatim.openstreetmap.org/reverse');
  u.searchParams.set('format','jsonv2');u.searchParams.set('lat',String(lat));u.searchParams.set('lon',String(lon));u.searchParams.set('zoom','10');u.searchParams.set('addressdetails','1');u.searchParams.set('accept-language',currentLanguage());
  const res=await fetch(u.toString(),{headers:{Accept:'application/json'}});
  if(!res.ok)throw new Error('reverse_geocode_'+res.status);
  const data=await res.json();
  const place=approximatePlaceFromAddress(data?.address);
  if(!place)throw new Error('reverse_geocode_empty');
  return place
}
async function fetchJsonWithTimeout(url,ms=3200){
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),ms);
  try{
    const res=await fetch(url,{headers:{Accept:'application/json'},cache:'no-store',signal:controller.signal});
    if(!res.ok)throw new Error('geo_http_'+res.status);
    return await res.json()
  }finally{clearTimeout(timer)}
}
async function approximatePlaceFromNetwork(){
  const providers=[
    async()=>{const d=await fetchJsonWithTimeout('https://ipwho.is/');if(d?.success===false)throw new Error('ipwho_failed');return [d?.city,d?.country].filter(Boolean).join(', ')},
    async()=>{const d=await fetchJsonWithTimeout('https://ipapi.co/json/');return [d?.city,d?.country_name].filter(Boolean).join(', ')}
  ];
  for(const provider of providers){
    try{const place=(await provider()).trim();if(place&&place.includes(','))return place}catch{}
  }
  throw new Error('network_location_unavailable')
}
async function prefillCurrentLocation(input,status){
  if(!input)return;
  let cached=null;try{cached=JSON.parse(sessionStorage.getItem(GEO_SESSION_KEY)||'null')}catch{}
  if(cached?.place&&Date.now()-(cached.at||0)<15*60*1000){input.value=cached.place;if(status)status.textContent=cached.source==='network'?T('locatedNetwork'):T('located');return}
  if(status)status.textContent=T('locating');
  input.dataset.userEdited='0';
  input.addEventListener('input',()=>{input.dataset.userEdited='1'},{once:true});
  const apply=(place,source)=>{
    try{sessionStorage.setItem(GEO_SESSION_KEY,JSON.stringify({place,source,at:Date.now()}))}catch{}
    if(input.dataset.userEdited!=='1'&&!input.value.trim())input.value=place;
    if(status)status.textContent=source==='network'?T('locatedNetwork'):T('located')
  };
  if(navigator.geolocation){
    try{
      const pos=await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:false,timeout:6500,maximumAge:5*60*1000}));
      const place=await reversePlace(pos.coords.latitude,pos.coords.longitude);
      apply(place,'gps');
      return
    }catch{}
  }
  try{
    const place=await approximatePlaceFromNetwork();
    apply(place,'network')
  }catch{
    if(status)status.textContent=T('locationManual')
  }
}
