function actorByLineage(){const map=new Map();for(const e of state.events)if(e.type==='create'&&e.lineageId&&e.actorId)map.set(e.lineageId,e.actorId);return map}
function ownerActor(m){return actorByLineage().get(m?.lineageId)||null}
function owned(m){return ownerActor(m)===PERSONA}
function normalizeMeta(m){if(!m)return m;const x={...m};x.owner=owned(x);x.ownerActorId=ownerActor(x);return x}
function lineage(m){return semantic.filter(x=>x.lineageId===m.lineageId)}
function rootFor(m){return lineage(m).find(x=>x.kind==='create')||m}
function parentFor(m){return m.parentSemanticId?byId.get(m.parentSemanticId):null}
function childrenOf(m,kind){return lineage(m).filter(x=>x.parentSemanticId===m.semanticId&&(!kind||x.kind===kind))}
function descendants(m){const out=new Set([m.semanticId]);let changed=true;while(changed){changed=false;for(const x of lineage(m))if(x.parentSemanticId&&out.has(x.parentSemanticId)&&!out.has(x.semanticId)){out.add(x.semanticId);changed=true}}return out}
function hasActiveDescendants(m){const ids=descendants(m);return semantic.some(x=>x.semanticId!==m.semanticId&&ids.has(x.semanticId)&&x.state==='alive')}
