function lineageLeaves(m){const ids=descendants(m);return lineage(m).filter(x=>ids.has(x.semanticId)&&childrenOf(x).length===0)}
function wholeWishBloomReady(m){const root=rootFor(m);if(!root||root.state!=='alive')return false;const leaves=lineageLeaves(root).filter(x=>x.semanticId!==root.semanticId);return leaves.length>0&&leaves.every(x=>x.state==='bloom')}
function abandonedAncestors(m){const out=[];let p=parentFor(m),guard=0;while(p&&guard++<100){if(p.state==='abandoned')out.push(p);p=parentFor(p)}return out.reverse()}
