function lastCloseBranch(semanticId){for(let i=state.events.length-1;i>=0;i--){const e=state.events[i];if(e.type==='close_branch'&&e.semanticId===semanticId)return e}return null}
function resumeLineageIds(m){const close=lastCloseForLineage(m.lineageId),ids=Array.isArray(close?.semanticIds)?close.semanticIds:lineage(m).map(x=>x.semanticId);return ids.filter(id=>byId.get(id)?.state==='abandoned')}
function resumeBranchIds(m){const close=lastCloseBranch(m.semanticId),ids=Array.isArray(close?.semanticIds)?close.semanticIds:[];return ids.filter(id=>byId.get(id)?.state==='abandoned')}
const V42_VITALITY={fadeStartDays:4,notifyDays:14,lateNotifyDays:25,dormantDays:30};
const V42_TOUCH_TYPES=new Set(['create','evolve','split','branch_add','bloom','correct','reparent','resume','resume_branch','resume_lineage','wake']);
function lineageSemanticIds(lineageId){return new Set(semantic.filter(x=>x.lineageId===lineageId).map(x=>x.semanticId))}
function vitalityForLineage(lineageId,now=Date.now()){
  const owner=actorByLineage().get(lineageId),ids=lineageSemanticIds(lineageId);
  let lastAt=0;
  for(const ev of state.events){
    if(!V42_TOUCH_TYPES.has(ev.type))continue;
    if(owner&&ev.actorId&&ev.actorId!==owner&&ev.actorId!=='system')continue;
    const belongs=ev.lineageId===lineageId||ids.has(ev.semanticId)||(Array.isArray(ev.children)&&ev.children.some(x=>ids.has(x.semanticId)));
    if(!belongs)continue;
    const at=Number(ev.at)||0;
    if(at>lastAt)lastAt=at;
  }
  if(!lastAt)return{status:'vital',days:0,vigor:1,lastAt:0};
  const days=Math.max(0,Math.floor((now-lastAt)/DAY));
  let vigor=1,status='vital';
  if(days>=V42_VITALITY.dormantDays){status='dormant';vigor=.28}
  else if(days>=V42_VITALITY.fadeStartDays){
    status='fading';
    if(days<14)vigor=Math.max(.76,.96-(days-3)*.018);
    else vigor=Math.max(.38,.76-(days-14)*.025);
  }else vigor=Math.max(.96,1-days*.012);
  return{status,days,vigor:Number(vigor.toFixed(3)),lastAt}
}
function applyVitalityToSemantic(){
  for(const m of semantic){
    if(!owned(m)||m.state!=='alive'){m.vitality=null;continue}
    m.vitality=vitalityForLineage(m.lineageId)
  }
}
function vitalityFor(m){return m?.vitality||null}
function isDormant(m){return m?.state==='alive'&&vitalityFor(m)?.status==='dormant'}
function sendVitality(){
  if(!engineReady)return;
  const map={};
  for(const root of semantic.filter(x=>x.owner&&x.kind==='create'&&x.state==='alive')){
    const v=vitalityFor(root)||vitalityForLineage(root.lineageId);
    if(v)map[root.lineageId]=v
  }
  send({type:'rv42-vitality',map})
}
function addVitalityNotification(root,key,title,body){
  state.notifications=Array.isArray(state.notifications)?state.notifications:[];
  const id='v42-vitality|'+root.lineageId+'|'+key;
  if(state.notifications.some(n=>n.id===id))return false;
  state.notifications.unshift({id,kind:'vitality',objectId:root.semanticId,title,body,isRead:false,at:Date.now()});
  return true
}
function ensureVitalityNotifications(){
  let changed=false;
  for(const root of semantic.filter(x=>x.owner&&x.kind==='create'&&x.state==='alive')){
    const v=vitalityFor(root);
    if(!v)continue;
    if(v.days>=V42_VITALITY.notifyDays)changed=addVitalityNotification(root,'fade14',state.lang==='fr'?'Ton wish perd un peu de sa lumière':'Your wish is losing some light',state.lang==='fr'?'Cela fait '+v.days+' jours sans nouvelle action significative.':'It has been '+v.days+' days since a meaningful action.')||changed;
    if(v.days>=V42_VITALITY.lateNotifyDays)changed=addVitalityNotification(root,'fade25',state.lang==='fr'?'Ton wish approche de la dormance':'Your wish is getting close to dormancy',state.lang==='fr'?'Une petite action suffit encore à lui redonner de la vigueur.':'One small action is enough to restore its vitality.')||changed;
    if(v.status==='dormant')changed=addVitalityNotification(root,'dormant30',state.lang==='fr'?'Ton wish est devenu dormant':'Your wish has gone dormant',state.lang==='fr'?'Sa trace reste dans le monde. Tu peux le réveiller quand tu veux.':'Its trace remains in the world. You can wake it whenever you want.')||changed;
  }
  if(changed)save()
}
function currentEvolutionRepresentative(root){
  if(!root||root.state!=='alive')return null;
  let cur=root,guard=0,next=null;
  while(guard++<100&&(next=evolveChild(cur)))cur=next;
  return cur?.state==='alive'?cur:null
}
function entrustedEligible(m){
  if(!m||m.state!=='alive'||isSuperseded(m))return false;
  if(m.owner)return false;
  if(m.vitality?.status==='dormant')return false;
  return true
}
