    realForeignRoots=semantic.filter(m=>SHARED&&!m.simulated&&!owned(m)&&m.kind==='create'),
    sourceRoots=SHARED?[...realForeignRoots,...simulatedRoots]:simulatedRoots,
    roots=sourceRoots.map(currentEvolutionRepresentative).filter(entrustedEligible);
